curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&exclude_archived=true" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(ch['id'], ch['name'])
else:
    print(data)
